values.content:
Write a job description.

Role: {{ $json.jobTitle }}
Company: {{ $json.companyName }}
Department: {{ $json.department || 'not specified' }}
Seniority: {{ $json.seniorityLevel }}
Employment type: {{ $json.employmentType.replace(/_/g,' ') }}
Location: {{ $json.location || 'not specified' }}
Remote policy: {{ $json.remotePolicy.replace(/_/g,' ') }}
Company stage: {{ $json.companyStage || 'not specified' }}
Salary range: {{ $json.salaryRange || 'not specified' }}

Company mission:
{{ $json.companyMission || 'not provided' }}

Team description:
{{ $json.teamDescription || 'not provided — derive from role' }}

Role description:
{{ $json.roleDescription || 'not provided — derive from title and seniority' }}

Must-have requirements:
{{ $json.mustHaveRequirements.join('\n') || 'not specified — derive from role' }}

Nice-to-have requirements:
{{ $json.niceToHaveRequirements.join('\n') || 'none specified' }}

Benefits:
{{ $json.benefits.join(', ') || 'not specified' }}

Hiring manager notes:
{{ $json.hiringManagerNotes || 'none' }}

Tone: {{ $json.tone.replace(/_/g,' ') }}

Return JSON:
{"job_description":{"headline":"1-2 sentence hook — why this specific role at this specific company is interesting right now","about_the_role":"2-3 paragraphs: what the person will do, what they'll own, what success looks like in year one. Specific, not generic.","about_the_team":"1-2 sentences on team size, how it works, who they'll work with","what_youll_do":["specific responsibility — start with a verb, be concrete"],"what_we_need":{"must_have":["non-negotiable requirement — specific and justified"],"nice_to_have":["things that would be a plus"]},"about_the_company":"2-3 sentences — mission, stage, what makes this an interesting place to be","compensation_and_benefits":"salary range and benefits in plain language","honest_about_the_role":"1-2 sentences being upfront about challenges or realities of this role — what it's NOT","how_to_apply":"what the process looks like and what they should include"},"inclusion_flags":["specific phrases in this JD that may unnecessarily filter candidates — suggestions to make it more inclusive"],"posting_headline":"short job board headline under 60 chars","linkedin_summary":"under 300 chars for LinkedIn posting"}
